@Mod.EventBusSubscriber(modid="efn", bus=Mod.EventBusSubscriber.Bus.MOD)
public class CrescentMoon {
    public static Skill crescentmoon;
    public static ComboNode Strike_Extend;

    @SubscribeEvent
    public static void BuildSkills(SkillBuildEvent event) {
        SkillBuildEvent.ModRegistryWorker registryWorker = event.createRegistryWorker("efn");
        ComboNode root = ComboNode.create();
        ComboNode Dash = ComboNode.createNode(EFNFalchionAnimations.FALCHION_DASHATTACK).setPriority(5).addCondition((Condition)new EFNSprintingCondition());
        ComboNode Air = ComboNode.createNode(EFNFalchionAnimations.FALCHION_AIRSLASH).setPriority(5).addCondition((Condition)new JumpCondition()).addCondition((Condition)new EFNStaminaCondition(3.0f, true)).addTimeEvent(TimeEvents.timeConsumeStamina(0.3f, 3.0f));
        ComboNode Auto1 = ComboNode.createNode(EFNFalchionAnimations.FALCHION_AUTO1).setPriority(1).addTimeEvent(TimeEvents.TimeSimulationAttackEvent(1.3f));
        ComboNode Auto2 = ComboNode.createNode(EFNFalchionAnimations.FALCHION_AUTO2).addTimeEvent(TimeEvents.TimeSimulationAttackEvent(1.2f));
        ComboNode Auto3 = ComboNode.createNode(EFNFalchionAnimations.FALCHION_AUTO3).addTimeEvent(TimeEvents.TimeSimulationAttackEvent(1.3f));
        ComboNode Skill2 = ComboNode.createNode(EFNFalchionAnimations.FALCHION_SKILL).setCanBeInterrupt(false).addCondition((Condition)new EFNStackCondition(1, Integer.MAX_VALUE)).addCondition((Condition)new CooldownCondition(false)).setCooldown(600);
        Strike_Extend = ComboNode.createNode(EFNFalchionAnimations.FALCHION_EX2).setPriority(10).setCanBeInterrupt(false).addCondition((Condition)new MobEffectCondition(false, EFNMobEffectRegistry.COMBO_EXECUTE_WINDOW, 0, Integer.MAX_VALUE));
        ComboNode Strike = ComboNode.createNode(EFNFalchionAnimations.FALCHION_STRIKE).setPriority(10).addCondition((Condition)new EFNStaminaCondition(4.0f, true)).addTimeEvent(TimeEvents.timeConsumeStamina(0.15f, 4.0f));
        ComboNode BasicAttack = ComboNode.create().addConditionNode(Dash).addConditionNode(Air).addConditionNode(Auto1);
        ComboNode BasicAttack_Strike = ComboNode.create().addConditionNode(Dash).addConditionNode(Air).addConditionNode(Auto1).addConditionNode(Strike_Extend);
        ComboNode Attack2 = ComboNode.create().addConditionNode(Dash).addConditionNode(Air).addConditionNode(Auto2);
        ComboNode Attack3 = ComboNode.create().addConditionNode(Dash).addConditionNode(Air).addConditionNode(Auto3);
        ComboNode Skills = ComboNode.create().addConditionNode(Skill2);
        root.key1(BasicAttack);
        root.key3(Skills);
        root.key4(Strike);
        Skill2.key1(BasicAttack);
        Skill2.key3(Skills);
        Skill2.key4(Strike);
        Dash.key1(BasicAttack);
        Dash.key3(Skills);
        Dash.key4(Strike);
        Strike.key1(BasicAttack_Strike);
        Strike.key3(Skills);
        Strike.key4(Strike);
        Strike_Extend.key1(BasicAttack);
        Strike_Extend.key3(Skills);
        Strike_Extend.key4(Strike);
        Air.key1(BasicAttack);

