import com.p1nero.invincible.skill.ComboBasicAttack;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import yesman.epicfight.api.animation.AnimationManager;
import yesman.epicfight.api.forgeevent.SkillBuildEvent;
import yesman.epicfight.data.conditions.Condition;
import yesman.epicfight.gameasset.Animations;
import yesman.epicfight.skill.Skill;
import yesman.epicfight.skill.SkillBuilder;

@Mod.EventBusSubscriber(modid="efn", bus=Mod.EventBusSubscriber.Bus.MOD)
public class ExampleCombo {
    public static Skill exampleCombo;

    @SubscribeEvent
    public static void onSkillBuild(SkillBuildEvent event) {
        SkillBuildEvent.ModRegistryWorker registryWorker = event.createRegistryWorker("efn");
        ComboNode root = ComboNode.create();
        ComboNode auto1 = ComboNode.createNode(EFNSwordAnimations.NF_SWORD_AUTO1);
        ComboNode auto2 = ComboNode.createNode(EFNSwordAnimations.NF_SWORD_AUTO2);
        ComboNode auto3 = ComboNode.createNode(EFNSwordAnimations.NF_SWORD_AUTO3);
        ComboNode auto4 = ComboNode.createNode(EFNSwordAnimations.NF_SWORD_AUTO4);
        ComboNode dash = ComboNode.createNode(EFNSwordAnimations.NF_SWORD_DASH).setPriority(1).addCondition((Condition)new SprintingCondition());
        ComboNode airslash = ComboNode.createNode(EFNSwordAnimations.NF_SWORD_AIRSLASH).setPriority(2).addCondition((Condition)new JumpCondition());
        ComboNode skill = ComboNode.createNode((AnimationManager.AnimationAccessor)Animations.SWEEPING_EDGE);
        ComboNode basicAttack = ComboNode.create().addConditionNode(auto1).addConditionNode(dash).addConditionNode(airslash);
        ComboNode attack2 = ComboNode.create().addConditionNode(auto2).addConditionNode(dash).addConditionNode(airslash);
        ComboNode attack3 = ComboNode.create().addConditionNode(auto3).addConditionNode(dash).addConditionNode(airslash);
        ComboNode attack4 = ComboNode.create().addConditionNode(auto4).addConditionNode(dash).addConditionNode(airslash);
        root.key1(basicAttack);
        skill.key1(basicAttack);
        skill.key3(skill);
        auto1.key1(attack2);
        auto2.key1(attack3);
        auto3.key1(attack4);
        auto4.key1(basicAttack);
        airslash.key1(basicAttack);
        dash.key1(basicAttack);
        root.addChildToSubtree((ComboType)ComboNode.ComboTypes.KEY_3, skill);
        exampleCombo = registryWorker.build("examplecombo", ExampleInnate::new, (SkillBuilder)ComboBasicAttack.createComboBasicAttack().setCombo(root));
    }
}

